defmodule Solution do def zigzag_level_order(nil), do: []; def zigzag_level_order(root), do: levels([root], false, []); defp levels([], _, result), do: Enum.reverse(result); defp levels(nodes, reverse, result) do values = Enum.map(nodes, &(&1.val)); values = if reverse, do: Enum.reverse(values), else: values; children = Enum.flat_map(nodes, fn node -> [node.left, node.right] end) |> Enum.reject(&is_nil/1); levels(children, not reverse, [values | result]) end end
